    close()
    do return end
    ::Lcart::
    if (player.class == Job_Merchant) or (player.class == Job_Blacksmith) then goto UseCart end
    mes "[Kafra]"
    mes "I am sorry.The Cart service is only provided for Merchant and Blacksmith Class."
    cutin("kafra_02", 255)
    close()
    do return end
    ::UseCart::
    mes "[Kafra]"
    mes "The Cart Fee is 800 Zeny. Do you want to Rent a Cart?"
    next()
    c = menu("Rent a Cart.", "Cancel.")
    if c == 1 then goto RentCart elseif c == 2 then goto RCCancel end
    ::RentCart::
    if player.zeny < 800 then goto RCNeedZenys end
    player.zeny = player.zeny - 800
    if v.CheckCart == 0 then do return end --[[ goto NoCartSkill: no such label in the source (Athena ends the script) ]] end
    if v.CheckCart == 1 then goto GetCart end
    ::GetCart::
    player.zeny = player.zeny - 800
    set_cart()
    mes "[Kafra]"
    mes "There you go.."
    cutin("kafra_08", 255)
    close()
    do return end
    ::RCNeedZenys::
    mes "[Kafra]"
    mes "Dear,you don't have enough Money. You need 800 Zeny."
    cutin("kafra_02", 255)
    close()
    do return end
    ::RCCancel::
    cutin("kafra_02", 255)
    close()
    do return end
    ::Lpass::
    if count_item(1084) < 1 then goto NeedKafraPass end
    ::NeedKafraPass::
    mes "[Kafra]"
    mes "Dear you need at least 1 passport."
    cutin("kafra_02", 255)
    close()
    do return end
    mes "[Kafra]"
    mes "Now you are Using a Kapra's Pass."
    take_item(1084, 1)
    next()
    mes "[Kafra]"
    mes "Under development"
    cutin("kafra_02", 255)
    close()
    do return end
    ::Lteleport::
    mes "[Kafra]"
    mes "Set your destination."
    next()
    c = menu("Izlude -> 900 z", "Geffen -> 1400 z", "Payon -> 1700 z", "Morroc -> 1800 z", "Cancel")
    if c == 1 then goto Izlude elseif c == 2 then goto Geffen elseif c == 3 then goto Payon elseif c == 4 then goto Morroc elseif c == 5 then goto Cancel end
    ::Izlude::
    if player.zeny < 900 then do return end --[[ goto cantTeleport: no such label in the source (Athena ends the script) ]] end
    player.zeny = player.zeny - 900
    warp("izlude", 91, 105)
    cutin("kafra_03", 255)
    close()
    do return end
    ::Geffen::
    if player.zeny < 2100 then do return end --[[ goto cantTeleport: no such label in the source (Athena ends the script) ]] end
    player.zeny = player.zeny - 2100
    warp("geffen", 120, 39)
    cutin("kafra_03", 255)
    close()
    do return end
    ::Morroc::
    if player.zeny < 2100 then do return end --[[ goto cantTeleport: no such label in the source (Athena ends the script) ]] end
    player.zeny = player.zeny - 2100
    warp("morocc", 156, 46)
    cutin("kafra_03", 255)
    close()
    do return end
    ::Payon::
    if player.zeny < 2100 then do return end --[[ goto cantTeleport: no such label in the source (Athena ends the script) ]] end
    player.zeny = player.zeny - 2100
    warp("payon", 100, 100)
    cutin("kafra_03", 255)
    close()
    do return end
    ::Cancel::
    cutin("kafra_03", 255)
    close()
    do return end
    ::Lcancel::
    cutin("kafra_02", 255)
    close()
    do return end
    ::CantTeleport::
    mes "[Kafra]"
    mes "Dear you don't have enough money. Please check again."
    cutin("kafra_03", 255)
    close()
  end,
}

